import numpy as np
from causallearn.graph.GeneralGraph import GeneralGraph
from causallearn.graph.GraphNode import GraphNode

# =====================================================================
# EDITABLE: implement run_causal_discovery below
# =====================================================================
def run_causal_discovery(X: np.ndarray) -> GeneralGraph:
    """
    CIPS-GES: CI-Prior-guided refinement of Greedy Equivalence Search.

    1) A PC-stable style skeleton sweep with a reliability ("power") rule
       records, for every pair (i,j), the maximum p-value observed over all
       *reliable* chi-squared CI tests (test skipped if n < 5*df).
    2) These p-values define a soft log-prior on edges: pairs that were
       confidently separated (large max p) receive a penalty proportional
       to lam * log(p/alpha), capped at -pen_cap; never-separated pairs get
       zero penalty.
    3) GES (BDeu) provides a globally-searched CPDAG; a consistent DAG
       extension of it initializes hill climbing that optimizes
       BDeu-loss + prior-penalty. Deletions/reversals are allowed for any
       existing edge, additions only for CI-plausible candidate pairs.
       Random perturbation restarts escape local optima.
    4) The best DAG under the regularized objective is returned as a CPDAG.
    """
    import itertools
    import math
    import random

    from causallearn.utils.cit import CIT
    from causallearn.score.LocalScoreFunctionClass import LocalScoreClass
    from causallearn.score.LocalScoreFunction import local_score_BDeu
    from causallearn.utils.DAG2CPDAG import dag2cpdag

    rng = random.Random(0)
    n, N = X.shape
    alpha = 0.05
    max_depth = 3
    lam = 4.0
    # Trust CI evidence proportionally to sample size: p-values are more
    # reliable and BDeu deltas larger at large n, so scale the prior weight.
    lam = 4.0 * math.sqrt(n / 10000.0)

    cards = (X.max(axis=0).astype(int) + 1)

    cit = CIT(X, "chisq")

    # ---------------- Step 1: skeleton sweep, record max p-values --------
    adjm = np.ones((N, N), dtype=bool)
    np.fill_diagonal(adjm, False)
    maxp = np.zeros((N, N))

    def reliable(i, j, S):
        df = (cards[i] - 1) * (cards[j] - 1)
        for s in S:
            df *= cards[s]
        return n >= 5 * df

    for depth in range(0, max_depth + 1):
        neigh = {i: set(np.where(adjm[i])[0].tolist()) for i in range(N)}
        removals = []
        tested_any = False
        for i in range(N):
            for j in sorted(neigh[i]):
                if j <= i:
                    continue
                sep = False
                bases = [neigh[i] - {j}]
                if depth > 0:
                    bases.append(neigh[j] - {i})
                for base in bases:
                    if sep or len(base) < depth:
                        continue
                    for S in itertools.combinations(sorted(base), depth):
                        if not reliable(i, j, S):
                            continue
                        tested_any = True
                        p = cit(i, j, list(S))
                        if p is None or math.isnan(p):
                            continue
                        if p > maxp[i, j]:
                            maxp[i, j] = maxp[j, i] = p
                        if p > alpha:
                            sep = True
                            break
                if sep:
                    removals.append((i, j))
        for i, j in removals:
            adjm[i, j] = adjm[j, i] = False
        if not tested_any:
            break

    # ---------------- Step 2: soft edge prior from CI evidence -----------
    W = np.zeros((N, N))
    for i in range(N):
        for j in range(N):
            if i == j:
                continue
            p = max(maxp[i, j], 1e-300)
            w = lam * (math.log(alpha) - math.log(p))  # <= 0 iff p > alpha
            W[i, j] = max(-pen_cap, min(0.0, w))
    cand = W > (-pen_cap + 1e-9)
    np.fill_diagonal(cand, False)

    # ---------------- Step 3a: GES initialization ------------------------
    from causallearn.search.ScoreBased.GES import ges

    ges_res = ges(
        X,
        score_func="local_score_BDeu",
        parameters={"sample_prior": 1.0, "structure_prior": 1.0},
    )
    gm = ges_res["G"].graph

    def has_path_m(src, tgt, A):
        stack = [src]
        visited = set()
        while stack:
            u = stack.pop()
            if u == tgt:
                return True
            if u in visited:
                continue
            visited.add(u)
            stack.extend(np.where(A[u] == 1)[0].tolist())
        return False

    ges_adj = np.zeros((N, N), dtype=int)
    und_pairs = []
    for i in range(N):
        for j in range(N):
            if gm[i, j] == -1 and gm[j, i] == 1:
                ges_adj[i, j] = 1  # i --> j
            elif j > i and gm[i, j] == -1 and gm[j, i] == -1:
                und_pairs.append((i, j))
    # orient undirected edges greedily without creating cycles
    for i, j in und_pairs:
        if not has_path_m(j, i, ges_adj):
            ges_adj[i, j] = 1
        elif not has_path_m(i, j, ges_adj):
            ges_adj[j, i] = 1

    # ---------------- Step 3b: prior-regularized hill climbing -----------
    score_obj = LocalScoreClass(
        data=X, local_score_fun=local_score_BDeu, parameters=None
    )
    memo = {}

    def sc(j, pa):
        key = (j, tuple(sorted(int(x) for x in pa)))
        v = memo.get(key)
        if v is None:
            v = score_obj.score(j, sorted(int(x) for x in pa))
            memo[key] = v
        return v

    def climb(A, ls):
        while True:
            best_delta = -1e-6
            best_op = None
            for i in range(N):
                for j in range(N):
                    if i == j:
                        continue
                    if A[i, j] == 0 and A[j, i] == 0:
                        if not cand[i, j]:
                            continue
                        if has_path_m(j, i, A):
                            continue
                        pa = np.where(A[:, j] == 1)[0].tolist()
                        d = sc(j, pa + [i]) - ls[j] - W[i, j]
                        if d < best_delta:
                            best_delta, best_op = d, ("a", i, j)
                    elif A[i, j] == 1:
                        pa = np.where(A[:, j] == 1)[0].tolist()
                        pa_wo = [p for p in pa if p != i]
                        d = sc(j, pa_wo) - ls[j] + W[i, j]
                        if d < best_delta:
                            best_delta, best_op = d, ("d", i, j)
                        A[i, j] = 0
                        if not has_path_m(i, j, A):
                            pai = np.where(A[:, i] == 1)[0].tolist()
                            d = (sc(j, pa_wo) - ls[j]) + (
                                sc(i, pai + [j]) - ls[i]
                            )
                            if d < best_delta:
                                best_delta, best_op = d, ("r", i, j)
                        A[i, j] = 1
            if best_op is None:
                return A, ls
            op, i, j = best_op
            if op == "a":
                A[i, j] = 1
            elif op == "d":
                A[i, j] = 0
            else:
                A[i, j] = 0
                A[j, i] = 1
            ls[j] = sc(j, np.where(A[:, j] == 1)[0].tolist())
            if op == "r":
                ls[i] = sc(i, np.where(A[:, i] == 1)[0].tolist())

    def total(A, ls):
        t = float(np.sum(ls))
        for i, j in zip(*np.where(A == 1)):
            t -= W[i, j]
        return t

    def local_scores(A):
        return np.array(
            [sc(j, np.where(A[:, j] == 1)[0].tolist()) for j in range(N)],
            dtype=float,
        )

    best_adj, best_total = None, np.inf
    for A0 in (ges_adj.copy(), np.zeros((N, N), dtype=int)):
        A1, ls1 = climb(A0, local_scores(A0))
        t1 = total(A1, ls1)
        if t1 < best_total - 1e-6:
            best_total, best_adj = t1, A1.copy()

    # perturbation restarts
    for _ in range(2):
    for _ in range(3):
        edges = list(zip(*np.where(A2 == 1)))
        rng.shuffle(edges)
        k = max(1, len(edges) // 8)
        for (i, j) in edges[:k]:
            A2[i, j] = 0
            if rng.random() < 0.5 and not has_path_m(i, j, A2):
                A2[j, i] = 1
        A2, ls2 = climb(A2, local_scores(A2))
        t2 = total(A2, ls2)
        if t2 < best_total - 1e-6:
            best_total, best_adj = t2, A2.copy()

    # ---------------- Step 4: DAG -> CPDAG --------------------------------
    nodes = [GraphNode(f"X{i + 1}") for i in range(N)]
    G = GeneralGraph(nodes)
    for i in range(N):
        for j in range(N):
            if best_adj[i, j] == 1:
                G.add_directed_edge(nodes[i], nodes[j])
    return dag2cpdag(G)
# =====================================================================

