import numpy as np
from causallearn.graph.GeneralGraph import GeneralGraph
from causallearn.graph.GraphNode import GraphNode

# =====================================================================
# EDITABLE: implement run_causal_discovery below
#
# Soft-Superstructure Penalized Score search (SSPS):
#   1) PC-stable skeleton (chi-sq CI) defines a *soft* structural prior:
#      edges outside the CI skeleton pay a penalty lam = 2*ln(n) in a
#      penalized BDeu objective (unlike MMHC's hard restriction, true
#      edges wrongly removed by CI tests can still be recovered).
#   2) The penalized objective is minimized by hill-climbing with
#      add/delete/reverse moves + iterated local search (perturbation
#      restarts), with full local-score memoization.
#   3) The resulting DAG is converted to its CPDAG.
# =====================================================================
def run_causal_discovery(X: np.ndarray) -> GeneralGraph:
    """
    Input:  X of shape (n_samples, n_variables), integer-encoded discrete data
    Output: estimated CPDAG as causallearn.graph.GeneralGraph.GeneralGraph
    """
    from causallearn.utils.PCUtils import SkeletonDiscovery
    from causallearn.utils.cit import CIT
    from causallearn.score.LocalScoreFunctionClass import LocalScoreClass
    from causallearn.score.LocalScoreFunction import local_score_BDeu
    from causallearn.utils.DAG2CPDAG import dag2cpdag

    rng = np.random.RandomState(0)
    n, N = X.shape

    # ---------- Stage 1: CI skeleton -> soft superstructure prior ----------
    cit = CIT(X, "chisq")
    cg = SkeletonDiscovery.skeleton_discovery(
        X, 0.05, cit, stable=True, background_knowledge=None,
        verbose=False, show_progress=False, node_names=None)
    sk = (np.asarray(cg.G.graph) != 0)
    sk = np.logical_or(sk, sk.T)
    np.fill_diagonal(sk, False)
    lam_val = 2.0 * np.log(n)
    # Evidence-tiered soft prior: pairs that remain *marginally* dependent
    # but were removed only via conditioning (where chi-sq tests lose power)
    # get a reduced penalty; marginally independent pairs get full penalty.
    lam = np.full((N, N), lam_val)
    for i in range(N):
        for j in range(i + 1, N):
            if sk[i, j]:
                lam[i, j] = lam[j, i] = 0.0
            elif cit(i, j) < 0.01:
                lam[i, j] = lam[j, i] = 0.6 * lam_val
    np.fill_diagonal(lam, 0.0)

    # ---------- BDeu local score (negated: lower is better) + memo ----------
    score_func = LocalScoreClass(
        data=X, local_score_fun=local_score_BDeu, parameters=None)
    cache = {}

    def sc(j, pa):
        key = (j, pa)
        v = cache.get(key)
        if v is None:
            v = score_func.score(j, list(pa))
            cache[key] = v
        return v

    MAXP = 6

    def parents_of(adj, j):
        return tuple(np.where(adj[:, j] == 1)[0].tolist())

    def closure(adj):
        reach = np.zeros((N, N), dtype=bool)
        children = [np.where(adj[i] == 1)[0].tolist() for i in range(N)]
        for s in range(N):
            stack = [s]
            seen = reach[s]
            while stack:
                u = stack.pop()
                for c in children[u]:
                    if not seen[c]:
                        seen[c] = True
                        stack.append(c)
        return reach

    def has_path(adj, s, t):
        stack = [s]
        seen = set()
        while stack:
            u = stack.pop()
            if u == t:
                return True
            if u in seen:
                continue
            seen.add(u)
            stack.extend(np.where(adj[u] == 1)[0].tolist())
        return False

    def penalized(adj, local):
        return float(local.sum() + lam[adj == 1].sum())

    def hill_climb(adj):
        local = np.array([sc(j, parents_of(adj, j)) for j in range(N)])
        while True:
            reach = closure(adj)
            pa = [parents_of(adj, j) for j in range(N)]
            best_d, best_op = -1e-6, None
            # additions
            for j in range(N):
                if len(pa[j]) >= MAXP:
                    continue
                paj = pa[j]
                base = local[j]
                for i in range(N):
                    if i == j or adj[i, j] or adj[j, i] or reach[j, i]:
                        continue
                    newpa = tuple(sorted(paj + (i,)))
                    d = sc(j, newpa) - base + lam[i, j]
                    if d < best_d:
                        best_d, best_op = d, ("a", i, j)
            # deletions / reversals
            for i, j in np.argwhere(adj == 1):
                i, j = int(i), int(j)
                paj_del = tuple(p for p in pa[j] if p != i)
                d_del_j = sc(j, paj_del) - local[j]
                d = d_del_j - lam[i, j]
                if d < best_d:
                    best_d, best_op = d, ("d", i, j)
                if len(pa[i]) < MAXP:
                    adj[i, j] = 0
                    ok = not has_path(adj, i, j)
                    adj[i, j] = 1
                    if ok:
                        pai_new = tuple(sorted(pa[i] + (j,)))
                        d = d_del_j + sc(i, pai_new) - local[i]
                        if d < best_d:
                            best_d, best_op = d, ("r", i, j)
            if best_op is None:
                break
            op, i, j = best_op
            if op == "a":
                adj[i, j] = 1
            elif op == "d":
                adj[i, j] = 0
            else:
                adj[i, j] = 0
                adj[j, i] = 1
                local[i] = sc(i, parents_of(adj, i))
            local[j] = sc(j, parents_of(adj, j))
        return adj, penalized(adj, local)

    def perturb(adj, k):
        adj = adj.copy()
        for _ in range(k):
            edges = np.argwhere(adj == 1)
            u = rng.rand()
            if u < 0.4 and len(edges):
                i, j = edges[rng.randint(len(edges))]
                adj[i, j] = 0
            elif u < 0.7 and len(edges):
                i, j = edges[rng.randint(len(edges))]
                i, j = int(i), int(j)
                adj[i, j] = 0
                if adj[:, i].sum() < MAXP and not has_path(adj, i, j):
                    adj[j, i] = 1
                else:
                    adj[i, j] = 1
            else:
                cands = np.argwhere(sk & (adj == 0) & (adj.T == 0))
                if len(cands):
                    i, j = cands[rng.randint(len(cands))]
                    i, j = int(i), int(j)
                    if adj[:, j].sum() < MAXP and not has_path(adj, j, i):
                        adj[i, j] = 1
        return adj

    # ---------- Stage 2: GES warm start + penalized hill-climbing + ILS ----
    def ges_init():
        from causallearn.search.ScoreBased.GES import ges
        from causallearn.utils.PDAG2DAG import pdag2dag
        res = ges(X, score_func="local_score_BDeu",
                  parameters={"sample_prior": 1.0, "structure_prior": 1.0})
        dag = pdag2dag(res["G"])
        g = np.asarray(dag.graph)
        a = np.zeros((N, N), dtype=int)
        for i in range(N):
            for j in range(N):
                if g[j, i] == 1 and g[i, j] == -1:
                    a[i, j] = 1
        # enforce max-parent cap: greedily drop parents whose removal
        # most improves the penalized score
        for j in range(N):
            while a[:, j].sum() > MAXP:
                pa_j = tuple(np.where(a[:, j] == 1)[0].tolist())
                worst, worst_d = None, None
                for p in pa_j:
                    rest = tuple(q for q in pa_j if q != p)
                    d = sc(j, rest) - lam[p, j]
                    if worst_d is None or d < worst_d:
                        worst_d, worst = d, p
                a[worst, j] = 0
        return a

    adj, best_s = hill_climb(np.zeros((N, N), dtype=int))
    best_adj = adj.copy()
    try:
        adj2, s2 = hill_climb(ges_init())
        if s2 < best_s - 1e-9:
            best_s, best_adj = s2, adj2.copy()
    except Exception:
        pass
    k = max(3, int(0.15 * best_adj.sum()))
    for _ in range(15):
        cand = perturb(best_adj, k)
        cand, s = hill_climb(cand)
        if s < best_s - 1e-9:
            best_s, best_adj = s, cand.copy()

    # ---------- Stage 3: DAG -> CPDAG ----------
    nodes = [GraphNode(f"X{i + 1}") for i in range(N)]
    G = GeneralGraph(nodes)
    for i in range(N):
        for j in range(N):
            if best_adj[i, j] == 1:
                G.add_directed_edge(nodes[i], nodes[j])
    return dag2cpdag(G)
# =====================================================================
